#!/bin/sh
set -eu
mkdir -p outputs
printf '%s\n' "$*" >> outputs/aw-command-log.txt
real_aw() {
  "$AW_PLUGIN_EVAL_CLI_NODE" "$AW_PLUGIN_EVAL_CLI_ENTRY" "$@"
}
case "${1:-}" in
  review)
    case "${2:-}" in
      digest)
        if [ "${4:-}" != "--json" ] || [ -n "${5:-}" ]; then
          printf 'review digest requires one path and --json\n' >&2
          exit 9
        fi
        real_aw "$@"
        ;;
      publish)
        if [ "${3:-}" = "--help" ]; then
          printf 'Usage: aw review publish --kind <skill|workflow|aw-plugin|aw-workflow>\n'
          exit 0
        fi
        arguments=" $* "
        for required in " --kind aw-workflow " " --target author-review-flow " " --scope outputs/scope.json " " --report outputs/report.md " " --supersedes 20260824T120000Z-cccccccc-dddddddd "; do
          case "$arguments" in
            *"$required"*) : ;;
            *) printf 'missing delta workflow publication arguments\n' >&2; exit 9 ;;
          esac
        done
        prior_calls="$(cat outputs/aw-command-log.txt)"
        for required in "review digest plugins/author-side --json" "review digest plugins/reviewer-side --json"; do
          case "$prior_calls" in
            *"$required"*) : ;;
            *) printf 'missing required component digest before publication\n' >&2; exit 9 ;;
          esac
        done
        author_digest="$(real_aw review digest plugins/author-side --json)"
        reviewer_digest="$(real_aw review digest plugins/reviewer-side --json)"
        "$AW_PLUGIN_EVAL_CLI_NODE" -e '
const fs = require("node:fs");
const expected = new Map(process.argv.slice(1).map(JSON.parse).map((entry) => [entry.path, entry.digest]));
const ids = new Map([["plugins/author-side", "author-side"], ["plugins/reviewer-side", "reviewer-side"]]);
const scope = JSON.parse(fs.readFileSync("outputs/scope.json", "utf8"));
if (scope.kind !== "aw-workflow" || scope.id !== "author-review-flow" || !Array.isArray(scope.components) || scope.components.length !== expected.size) throw new Error("scope must contain the two workflow components");
const components = new Map(scope.components.map((component) => [component.path, component]));
for (const [componentPath, digest] of expected) {
  const component = components.get(componentPath);
  if (!component || component.kind !== "aw-plugin" || component.id !== ids.get(componentPath) || component.digest !== digest) throw new Error("scope components must use real review digest results");
}
' "$author_digest" "$reviewer_digest"
        printf '%s\n' '20260825T130000Z-aaaaaaaa-bbbbbbbb' > outputs/review-id.txt
        printf 'Published review 20260825T130000Z-aaaaaaaa-bbbbbbbb: reports/reviews/aw-workflow/id-author-review-flow/20260825T130000Z-aaaaaaaa-bbbbbbbb\n'
        ;;
      verify)
        test -f outputs/review-id.txt
        printf 'verified\n'
        ;;
      list)
        test -f outputs/review-id.txt
        printf '20260825T130000Z-aaaaaaaa-bbbbbbbb aw-workflow author-review-flow\n'
        ;;
      show)
        test -f outputs/review-id.txt
        printf 'Review: 20260825T130000Z-aaaaaaaa-bbbbbbbb\n'
        ;;
      *) exit 9 ;;
    esac
    ;;
  *) exit 9 ;;
esac
